source:
source note sys.dataset(fields: [title, subtitle, status, as_of, metric1_value, metric2_value, summary])

copy app { class: vocabulary, en: "Mail" }
copy sim { class: vocabulary, en: "Simulation" }
copy gist { class: model-copy, en: "Fictional OctoSense test message: no real shipment, carrier or purchase exists behind these details." }

view root Surface(pad: .tight) {
  Col(gap: 6) {
    Row(gap: 8, align: .center) {
      Icon(name: .mail, size: .row)
      TextCaption(text: copy.app, width: .fill)
      TextCaption(value: note.as_of)
    }
    Row(gap: 6, align: .center) {
      TextCaption(text: copy.sim)
      TextCaption(value: note.status)
    }
    TextTitle(text: note.title, width: .fill)
    TextCaption(value: note.subtitle)
    TextBody(text: note.metric1_value, width: .fill)
    TextBody(text: note.metric2_value, width: .fill)
    TextBody(text: note.summary, width: .fill)
    TextCaption(text: copy.gist, width: .fill)
  }
}
